public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int X = fs.nextInt();

        // If X == 0, every non-empty sequence has many contiguous subsequences,
        // and length-1 subsequence [0] sums to 0 whenever a 0 appears.
        // But also empty subsequence is usually not considered contiguous subsequence.
        // So we must avoid any element 0. Digits are {0,1,2}, hence answer = 2^N.
        if (X == 0) {
            System.out.println(modPow(2, N));
            return;
        }

        // DP over suffix sums < X that can be formed by contiguous suffixes ending at current position.
        // State bitmask S on bits 0..X-1:
        // bit s = 1 iff there exists a contiguous suffix of current sequence with sum s.
        // Empty suffix sum 0 always exists, so bit 0 is always 1.
        //
        // Transition by appending d in {0,1,2}:
        // new suffix sums are {d + s | s in old, d+s < X} plus 0 (empty suffix).
        // If any d+s == X, forbidden.
        //
        // Reachable masks are generated from start mask {0}.
        // Then do DP on those masks for N steps.

        int maxMaskBits = X;
        if (maxMaskBits > 25) {
            // Fallback for larger X: reachable states are still often small, but int mask won't fit.
            // Use long if possible.
            if (maxMaskBits <= 63) {
                solveLongMask(N, X);
                return;
            } else {
                // For very large X, no contiguous subsequence can sum to X unless total sum can reach X.
                // Since each element <= 2, total sum <= 2N.
                if (X > 2L * N) {
                    System.out.println(modPow(3, N));
                    return;
                }
                // For constraints where X > 63 and X <= 2N, this generic bitmask approach is not feasible.
                // Problem constraints in intended setting keep X small enough.
                throw new RuntimeException("X too large for this implementation");
            }
        }

        int start = 1; // only sum 0 present
        HashMap<Integer, Integer> id = new HashMap<>();
        ArrayList<Integer> masks = new ArrayList<>();
        ArrayList<int[]> trans = new ArrayList<>();

        Queue<Integer> q = new ArrayDeque<>();
        id.put(start, 0);
        masks.add(start);
        q.add(start);

        while (!q.isEmpty()) {
            int mask = q.poll();
            int[] nxt = new int[3];
            for (int d = 0; d <= 2; d++) {
                int nm = transitionInt(mask, d, X);
                nxt[d] = nm; // -1 means forbidden
                if (nm != -1 && !id.containsKey(nm)) {
                    id.put(nm, masks.size());
                    masks.add(nm);
                    q.add(nm);
                }
            }
            trans.add(nxt);
        }

        int m = masks.size();
        long[] dp = new long[m];
        long[] ndp = new long[m];
        dp[0] = 1;

        for (int i = 0; i < N; i++) {
            Arrays.fill(ndp, 0);
            for (int s = 0; s < m; s++) {
                long cur = dp[s];
                if (cur == 0) continue;
                int[] nxt = trans.get(s);
                for (int d = 0; d <= 2; d++) {
                    int nm = nxt[d];
                    if (nm == -1) continue;
                    int ni = id.get(nm);
                    ndp[ni] += cur;
                    if (ndp[ni] >= MOD) ndp[ni] -= MOD;
                }
            }
            long[] tmp = dp;
            dp = ndp;
            ndp = tmp;
        }

        long ans = 0;
        for (long v : dp) {
            ans += v;
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans);
    }

    static int transitionInt(int mask, int d, int X) {
        int nm = 1; // empty suffix sum 0
        for (int s = 0; s < X; s++) {
            if (((mask >> s) & 1) == 0) continue;
            int ns = s + d;
            if (ns == X) return -1;
            if (ns < X) nm |= (1 << ns);
        }
        return nm;
    }

    static void solveLongMask(int N, int X) {
        long start = 1L;
        HashMap<Long, Integer> id = new HashMap<>();
        ArrayList<Long> masks = new ArrayList<>();
        ArrayList<long[]> trans = new ArrayList<>();

        Queue<Long> q = new ArrayDeque<>();
        id.put(start, 0);
        masks.add(start);
        q.add(start);

        while (!q.isEmpty()) {
            long mask = q.poll();
            long[] nxt = new long[3];
            for (int d = 0; d <= 2; d++) {
                long nm = transitionLong(mask, d, X);
                nxt[d] = nm; // -1 means forbidden
                if (nm != -1L && !id.containsKey(nm)) {
                    id.put(nm, masks.size());
                    masks.add(nm);
                    q.add(nm);
                }
            }
            trans.add(nxt);
        }

        int m = masks.size();
        long[] dp = new long[m];
        long[] ndp = new long[m];
        dp[0] = 1;

        for (int i = 0; i < N; i++) {
            Arrays.fill(ndp, 0);
            for (int s = 0; s < m; s++) {
                long cur = dp[s];
                if (cur == 0) continue;
                long[] nxt = trans.get(s);
                for (int d = 0; d <= 2; d++) {
                    long nm = nxt[d];
                    if (nm == -1L) continue;
                    int ni = id.get(nm);
                    ndp[ni] += cur;
                    if (ndp[ni] >= MOD) ndp[ni] -= MOD;
                }
            }
            long[] tmp = dp;
            dp = ndp;
            ndp = tmp;
        }

        long ans = 0;
        for (long v : dp) {
            ans += v;
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans);
    }

    static long transitionLong(long mask, int d, int X) {
        long nm = 1L;
        for (int s = 0; s < X; s++) {
            if (((mask >> s) & 1L) == 0) continue;
            int ns = s + d;
            if (ns == X) return -1L;
            if (ns < X) nm |= (1L << ns);
        }
        return nm;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

