#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, X;
    cin >> N >> X;

    // If X = 0, every non-empty sequence has a contiguous subsequence summing to 0
    // (any single 0), and even without 0, the empty subsequence is usually not counted.
    // Since contiguous subsequence means non-empty, sequences without 0 are valid.
    // But the standard prefix-sum transition below assumes positive X.
    // Handle X=0 separately: forbid value 0 anywhere.
    if (X == 0) {
        long long ans = 1;
        for (long long i = 0; i < N; ++i) ans = ans * 2 % MOD; // only 1 or 2
        cout << ans % MOD << '\n';
        return 0;
    }

    int M = (int)X;
    // State bitmask S over sums 0..X-1:
    // bit i = 1 iff there exists a suffix of current sequence with sum i.
    // bit 0 is always 1 (empty suffix).
    //
    // Appending digit d transforms:
    // new suffix sums = {0} union {s+d | s in old, s+d < X}
    // If any s+d == X, sequence becomes forbidden.
    //
    // DP over reachable masks.

    unordered_map<unsigned long long, long long> dp, ndp;
    dp.reserve(1 << 16);
    ndp.reserve(1 << 16);

    unsigned long long init = 1ULL; // only sum 0
    dp[init] = 1;

    auto shift_mask = [&](unsigned long long mask, int d) -> unsigned long long {
        if (d == 0) return mask;
        if (d >= 64) return 1ULL; // only possible if X large, but then mask won't fit anyway
        unsigned long long shifted = (mask << d);
        if (M < 64) shifted &= ((1ULL << M) - 1ULL);
        return shifted | 1ULL;
    };

    if (X <= 63) {
        for (long long step = 0; step < N; ++step) {
            ndp.clear();
            for (auto &it : dp) {
                unsigned long long mask = it.first;
                long long ways = it.second;

                for (int d = 0; d <= 2; ++d) {
                    bool bad = false;
                    if (d <= M) {
                        int need = M - d;
                        if (0 <= need && need < 64) {
                            if ((mask >> need) & 1ULL) bad = true;
                        }
                    }
                    if (bad) continue;

                    unsigned long long nmask = shift_mask(mask, d);
                    long long &ref = ndp[nmask];
                    ref += ways;
                    if (ref >= MOD) ref -= MOD;
                }
            }
            dp.swap(ndp);
        }

        long long ans = 0;
        for (auto &it : dp) {
            ans += it.second;
            if (ans >= MOD) ans -= MOD;
        }
        cout << ans % MOD << '\n';
        return 0;
    }

    // For larger X, use bitset represented by vector<uint64_t>.
    // Since sums increase by at most 2 per step, only sums up to 2N matter.
    // If X > 2N, no contiguous subsequence can sum to X.
    if (X > 2 * N) {
        long long ans = 1;
        for (long long i = 0; i < N; ++i) ans = ans * 3 % MOD;
        cout << ans << '\n';
        return 0;
    }

    int LIM = (int)min<long long>(X, 2 * N + 1);
    int W = (LIM + 63) >> 6;

    struct VecHash {
        size_t operator()(const vector<unsigned long long>& v) const {
            size_t h = 0;
            for (auto x : v) {
                h ^= std::hash<unsigned long long>()(x + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2));
            }
            return h;
        }
    };

    unordered_map<vector<unsigned long long>, long long, VecHash> dp2, ndp2;
    vector<unsigned long long> start(W, 0);
    start[0] |= 1ULL; // sum 0
    dp2[start] = 1;

    auto test_bit = [&](const vector<unsigned long long>& v, int pos) -> bool {
        if (pos < 0 || pos >= LIM) return false;
        return (v[pos >> 6] >> (pos & 63)) & 1ULL;
    };

    auto shift_add = [&](const vector<unsigned long long>& v, int d) {
        vector<unsigned long long> res(W, 0);
        if (d == 0) {
            res = v;
            res[0] |= 1ULL;
            return res;
        }
        int ws = d >> 6;
        int bs = d & 63;
        for (int i = W - 1; i >= 0; --i) {
            unsigned long long val = 0;
            if (i - ws >= 0) {
                val |= v[i - ws] << bs;
                if (bs && i - ws - 1 >= 0) val |= v[i - ws - 1] >> (64 - bs);
            }
            res[i] = val;
        }
        int extra = (W << 6) - LIM;
        if (extra) res.back() &= (~0ULL >> extra);
        res[0] |= 1ULL;
        return res;
    };

    for (long long step = 0; step < N; ++step) {
        ndp2.clear();
        for (auto &it : dp2) {
            const auto &mask = it.first;
            long long ways = it.second;

            for (int d = 0; d <= 2; ++d) {
                int need = (int)X - d;
                if (test_bit(mask, need)) continue;

                auto nmask = shift_add(mask, d);
                long long &ref = ndp2[nmask];
                ref += ways;
                if (ref >= MOD) ref -= MOD;
            }
        }
        dp2.swap(ndp2);
    }

    long long ans = 0;
    for (auto &it : dp2) {
        ans += it.second;
        if (ans >= MOD) ans -= MOD;
    }
    cout << ans % MOD << '\n';
    return 0;
}

