static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N;
    int X;
    if (scanf("%lld %d", &N, &X) != 2) return 0;

    /* If X = 0, every non-empty sequence contains a contiguous subsequence
       with sum 0 only if it has a 0 element? Actually a single 0 gives sum 0.
       But also empty subsequence is not considered. We need no contiguous
       subsequence summing to 0. Since all elements are nonnegative, only 0's
       create such subsequences. So each position must be 1 or 2. */
    if (X == 0) {
        printf("%lld\n", mod_pow(2, N));
        return 0;
    }

    /* Let dp[s] = number of valid sequences whose suffix sums < X are represented
       by bitmask s over [0, X-1]:
       bit i = 1 iff there exists a suffix with sum i.
       Since all values are nonnegative and bounded, appending a in {0,1,2}
       transforms mask:
         new = ((old << a) | (1 << a)) & ((1<<X)-1)
       and transition is allowed iff bit X would not appear, i.e. no previous
       suffix sum X-a exists (or a==X via singleton, handled by checking).

       Reachable masks have a special form; we simply BFS/DP over masks.
       This is feasible for small/moderate X. */
    if (X >= 63) {
        /* For this problem setting, X is intended small enough for bitmask DP.
           If not, this approach is infeasible anyway. */
        return 0;
    }

    unsigned long long LIM = 1ULL << X;
    long long *dp = (long long*)calloc((size_t)LIM, sizeof(long long));
    long long *ndp = (long long*)calloc((size_t)LIM, sizeof(long long));
    if (!dp || !ndp) return 0;

    dp[0] = 1;

    unsigned long long fullmask = LIM - 1;

    for (long long step = 0; step < N; step++) {
        memset(ndp, 0, (size_t)LIM * sizeof(long long));
        for (unsigned long long mask = 0; mask < LIM; mask++) {
            long long cur = dp[mask];
            if (!cur) continue;

            for (int a = 0; a <= 2; a++) {
                if (a == X) continue; /* singleton [a] sums to X */
                if (a < X) {
                    int bad = 0;
                    if (X - a == 0) {
                        /* impossible here since a!=X and X>0 */
                    } else {
                        if ((mask >> (X - a)) & 1ULL) bad = 1;
                    }
                    if (bad) continue;

                    unsigned long long nmask = ((mask << a) | (1ULL << a)) & fullmask;
                    ndp[nmask] += cur;
                    if (ndp[nmask] >= MOD) ndp[nmask] -= MOD;
                }
            }
        }
        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    long long ans = 0;
    for (unsigned long long mask = 0; mask < LIM; mask++) {
        ans += dp[mask];
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans);

    free(dp);
    free(ndp);
    return 0;
}

